 const actualIncome=all.filter(x=>x.category.kind==='income').reduce((n,x)=>n+Number(actualValue(x.item)||0),0);
 const savings=all.filter(x=>x.item.flow==='savings').reduce((n,x)=>n+Number(x.item.planned||0),0);
