 const fixed=[new Date(year,0,1,12),new Date(year,11,25,12),new Date(year,11,26,12)],observed=[];
 for(const holiday of fixed){let observedDate=new Date(holiday);while(observedDate.getDay()===0||observedDate.getDay()===6||observed.some(x=>x.toDateString()===observedDate.toDateString()))observedDate.setDate(observedDate.getDate()+1);observed.push(observedDate);}
 const easter=easterSunday(year),goodFriday=new Date(easter);goodFriday.setDate(goodFriday.getDate()-2);const easterMonday=new Date(easter);easterMonday.setDate(easterMonday.getDate()+1);
